            ->pluck('code')
            ->map(fn ($code) => strtoupper(trim((string) $code)))
            ->flip()
            ->all();

        $pending = [];
        foreach ($airports as $airport) {
            if (!isset($existing[strtoupper($airport['code'])])) {
                $pending[] = $airport;
            }
        }

        foreach (array_chunk($pending, 500) as $chunk) {
            DB::table('airports')->insert($chunk);
        }

        $this->command?->info('Airport master import complete: ' . count($pending) . ' new IATA airports inserted.');
